'use client'
import { createContext, useEffect, useId, useImperativeHandle, useRef, type ReactNode, type Ref } from 'react'
import { useMenu } from '@/hooks/useMenu'
import { cn } from '@/lib/cn'

// A button that opens a short list of choices or actions (console2.css .v2-menu): a square panel in a hairline, no
// shadow, 4px inside; rows from MenuItem. It comes in over 160ms, a 4px drop (a rise when it opens upward), and not at
// all when opened from the keyboard. Arrows, Home, End, Escape, Tab and a click outside are handled (useMenu).
// `offset` moves the panel in from its edge. The trigger's content is `trigger` (a node, or a function of `open`),
// drawn as a secondary button unless `triggerClass` says otherwise. `defaultOpen` opens it with the page; `ref` gets
// { open, show, close } (Vue's exposed open and close); `onOpenChange` hears it open and close. `data-ds` names the
// root for a component built on it (Vue's falls through: <Menu data-ds="account-menu">).
export const MenuClose = createContext<() => void>(() => {})

export interface MenuHandle { open: boolean, show: (focus?: 'first' | 'last' | 'none') => void, close: (refocus?: boolean) => void }
export interface MenuProps {
  label: string
  up?: boolean
  align?: 'start' | 'end'
  width?: string
  offset?: string
  triggerClass?: string
  triggerLabel?: string
  trigger?: ReactNode | ((open: boolean) => ReactNode)
  defaultOpen?: boolean
  onOpenChange?: (open: boolean) => void
  'data-ds'?: string
  className?: string
  children?: ReactNode
  ref?: Ref<MenuHandle>
}

export function Menu({ label, up, align = 'start', width = '264px', offset = '0px', triggerClass, triggerLabel, trigger: triggerContent, defaultOpen, onOpenChange, 'data-ds': ds = 'menu', className, children, ref }: MenuProps) {
  const { open, root, trigger, show, close, toggle, onTriggerKey, onMenuKey } = useMenu(defaultOpen)
  const report = useRef(onOpenChange)
  report.current = onOpenChange
  const was = useRef(open)
  useEffect(() => {
    if (was.current === open) return
    was.current = open
    report.current?.(open)
  }, [open])
  useImperativeHandle(ref, () => ({ open, show, close }), [open, show, close])
  const id = `menu-${useId()}`
  return (
    <MenuClose.Provider value={() => close(true)}>
      <style href="ds-menu" precedence="ds">{css}</style>
      <div data-ds={ds} ref={root} className={cn('relative inline-block', className)}>
        <button
          ref={trigger}
          type="button"
          className={triggerClass ?? 'inline-flex h-control-sm cursor-pointer items-center gap-1.5 border border-action-secondary-edge bg-surface px-2.5 text-meta leading-5 font-medium text-fg transition-[border-color,background-color] duration-120 ease-standard hover:border-action-secondary-edge-hover active:bg-surface-subtle aria-expanded:border-action-secondary-edge-hover max-md:h-control-touch max-md:text-ui'}
          aria-haspopup="menu"
          aria-expanded={open}
          aria-controls={id}
          aria-label={triggerLabel}
          onClick={toggle}
          onKeyDown={onTriggerKey}
        >
          {typeof triggerContent === 'function' ? triggerContent(open) : triggerContent}
        </button>
        {open && (
          <div
            id={id}
            className="ds-menu"
            data-up={up || undefined}
            style={{ width, [align === 'end' ? 'right' : 'left']: offset, [up ? 'bottom' : 'top']: 'calc(100% + 4px)' }}
            role="menu"
            aria-label={label}
            onKeyDown={onMenuKey}
          >
            {children}
          </div>
        )}
      </div>
    </MenuClose.Provider>
  )
}

export default Menu

const css = `
.ds-menu { position: absolute; z-index: 40; display: flex; flex-direction: column; padding: var(--ds-space-xs); border: var(--ds-border-hairline) solid var(--ds-color-edge); background: var(--ds-color-surface); animation: ds-menu-in var(--ds-duration-glide) var(--ds-easing-standard) both; scroll-margin: 8px; }
.ds-menu[data-up] { animation-name: ds-menu-up; }
/* Opened from the keyboard, focus lands on a row at once: no animation. */
.ds-menu:has(:focus-visible) { animation: none; }
.ds-menu > * { flex-shrink: 0; }
@keyframes ds-menu-in { from { opacity: 0; transform: translateY(-4px); } }
@keyframes ds-menu-up { from { opacity: 0; transform: translateY(4px); } }
@media (prefers-reduced-motion: reduce) { .ds-menu { animation: none; } }
`

'use client'
import { useContext, type ReactNode } from 'react'
import { MenuClose } from '@/components/ui/Menu'

// One row of a Menu (console2.css .v2-menu-item): 32px (44px on phones), 13px, a 14px gutter that holds the 4px red
// square marker of the row under the pointer or focus, which also takes the paper fill. `current` sets it in medium
// weight; `danger` is Sign out's red. Put a 14px Lucide icon first (text-fg-muted), a count or a check last.
// Choosing it calls `onSelect` and closes the menu, unless `keepOpen`. `role` and `aria-checked` make it a radio or
// checkbox row (role="menuitemradio" aria-checked={picked}), as Vue's fall through to the button.
export interface MenuItemProps { href?: string, current?: boolean, danger?: boolean, disabled?: boolean, keepOpen?: boolean, onSelect?: () => void, role?: 'menuitem' | 'menuitemradio' | 'menuitemcheckbox', 'aria-checked'?: boolean, className?: string, children?: ReactNode }

export function MenuItem({ href, current, danger, disabled, keepOpen, onSelect, role = 'menuitem', 'aria-checked': checked, className, children }: MenuItemProps) {
  const close = useContext(MenuClose)
  function choose() {
    onSelect?.()
    if (!keepOpen) close()
  }
  const shared = { 'data-ds': 'menu-item', role, 'aria-checked': checked, className: className ? `ds-menu-item ${className}` : 'ds-menu-item', 'aria-current': current ? 'true' as const : undefined, 'data-danger': danger || undefined, onClick: choose }
  return (
    <>
      <style href="ds-menu-item" precedence="ds">{css}</style>
      {href ? <a href={href} {...shared}>{children}</a> : <button type="button" disabled={disabled} {...shared}>{children}</button>}
    </>
  )
}

export default MenuItem

const css = `
.ds-menu-item { position: relative; display: flex; width: 100%; height: var(--ds-size-control-md); align-items: center; gap: var(--ds-space-md); padding: 0 10px 0 14px; color: var(--ds-color-fg); font-size: var(--ds-text-ui); text-align: left; outline: none; cursor: pointer; transition: background-color var(--ds-duration-micro) var(--ds-easing-standard); }
.ds-menu-item::before { position: absolute; top: 50%; left: 5px; width: 4px; height: 4px; margin-top: -2px; background: var(--ds-color-edge-accent); content: ""; opacity: 0; transition: opacity var(--ds-duration-micro) var(--ds-easing-standard); }
.ds-menu-item:focus-visible { background: var(--ds-color-surface-subtle); }
.ds-menu-item:focus-visible::before { opacity: 1; }
@media (hover: hover) and (pointer: fine) {
  .ds-menu-item:hover { background: var(--ds-color-surface-subtle); }
  .ds-menu-item:hover::before { opacity: 1; }
  .ds-menu-item[data-danger]:hover { background: var(--ds-color-surface-danger); }
}
.ds-menu-item[aria-current="true"] { font-weight: var(--ds-font-weight-medium); }
.ds-menu-item:disabled { color: var(--ds-color-fg-muted); cursor: progress; }
.ds-menu-item[data-danger] { color: var(--ds-color-fg-danger); }
.ds-menu-item[data-danger]:focus-visible { background: var(--ds-color-surface-danger); }
@media (pointer: coarse), (max-width: 767px) { .ds-menu-item { height: auto; min-height: 44px; } }
`

import type { ReactNode } from 'react'

// A group's name in a Menu (console2.css .v2-menu-label): 12px muted, an optional tag at the end.
export function MenuLabel({ children }: { children?: ReactNode }) {
  return <p data-ds="menu-label" className="flex items-center justify-between gap-2 pt-1.5 pr-2.5 pb-1 pl-3.5 text-meta text-fg-muted">{children}</p>
}

export default MenuLabel

// A hairline between a Menu's groups, edge to edge (console2.css .v2-menu-sep).
export function MenuSeparator() {
  return <div data-ds="menu-separator" className="-mx-1 my-1 h-px bg-edge" role="separator" />
}

export default MenuSeparator

'use client'
import { useCallback, useEffect, useRef, useState, type KeyboardEvent } from 'react'

/**
 * A menu button's behavior: it opens on click, arrows move between items (opening the menu on their end of it from the
 * button), Home and End jump, Escape closes and returns focus to the button, Tab and a click outside close it.
 */
export function useMenu(initial = false) {
  const [open, setOpen] = useState(initial)
  const root = useRef<HTMLDivElement | null>(null)
  const trigger = useRef<HTMLButtonElement | null>(null)
  const pending = useRef<'first' | 'last' | 'none' | null>(null)
  // Each show() renders, so an arrow on the open menu's button still focuses a row (Vue's nextTick runs either way).
  const [, setShown] = useState(0)

  const items = () => [...(root.current?.querySelectorAll<HTMLElement>('[role^="menuitem"]:not([disabled])') ?? [])]

  // After the menu renders: scroll it into view and focus the row asked for (Vue's nextTick).
  useEffect(() => {
    if (!open || !pending.current) return
    const focus = pending.current
    pending.current = null
    // Opened at the fold it would land out of sight, and the button would seem to do nothing.
    items()[0]?.closest('[role="menu"]')?.scrollIntoView({ block: 'nearest' })
    if (focus === 'none') return
    const list = items()
    ;(focus === 'last' ? list.at(-1) : list[0])?.focus()
  })

  const show = useCallback((focus: 'first' | 'last' | 'none' = 'first') => {
    pending.current = focus
    setOpen(true)
    setShown(n => n + 1)
  }, [])
  const close = useCallback((refocus = false) => {
    setOpen(false)
    if (refocus) trigger.current?.focus()
  }, [])
  function toggle() {
    if (open) close()
    else show('none')
  }
  function onTriggerKey(event: KeyboardEvent) {
    if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {
      event.preventDefault()
      show(event.key === 'ArrowDown' ? 'first' : 'last')
    }
    else if (event.key === 'Escape' && open) {
      event.preventDefault()
      close(true)
    }
  }
  function onMenuKey(event: KeyboardEvent) {
    const list = items()
    const at = list.indexOf(document.activeElement as HTMLElement)
    if (event.key === 'Escape') {
      event.preventDefault()
      close(true)
    }
    else if (event.key === 'Tab') {
      close()
    }
    else if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {
      event.preventDefault()
      const step = event.key === 'ArrowDown' ? 1 : -1
      list[(at + step + list.length) % list.length]?.focus()
    }
    else if (event.key === 'Home' || event.key === 'End') {
      event.preventDefault()
      ;(event.key === 'Home' ? list[0] : list.at(-1))?.focus()
    }
  }
  useEffect(() => {
    function outside(event: PointerEvent) {
      if (root.current && !root.current.contains(event.target as Node)) setOpen(false)
    }
    document.addEventListener('pointerdown', outside)
    return () => document.removeEventListener('pointerdown', outside)
  }, [])

  return { open, root, trigger, show, close, toggle, onTriggerKey, onMenuKey }
}

// Joins class names, skipping falsy ones: cn('a', on && 'b', ['c', undefined]). It does not merge conflicting
// utilities (no tailwind-merge), as Vue's class binding does not: the library's classes are written not to compete,
// and a className from the caller is appended after them, as Vue appends a fallthrough class.
export type ClassValue = string | false | null | undefined | 0 | ClassValue[]

export function cn(...values: ClassValue[]): string {
	const out: string[] = []
	for (const v of values) {
		if (!v) continue
		if (Array.isArray(v)) {
			const s = cn(...v)
			if (s) out.push(s)
		}
		else out.push(v)
	}
	return out.join(' ')
}
